  const Heading = headingLevel === 3 ? "h3" : "h2"
  return (
    <LearnerRoot
      as="section"
      contractKey="blocks.curriculum-journey"
      className={`learner-journey ${compact ? "learner-journey-compact" : ""} ${className ?? ""}`}
      aria-labelledby="learner-journey-title"
