        {messages.heading}
      </Heading>
      <ol className="learner-journey-list" data-learner-effect="trace">
        {items.map((item) => {
          const stateLabel = messages[item.state]
          const lockLabel =
            item.lockReason === "drip" ? messages.dripLock : messages.prerequisiteLock
          const icon = item.done ? (
            <Check aria-hidden />
          ) : item.state === "locked" ? (
            <Lock aria-hidden />
          ) : item.state === "current" ? (
            <Play aria-hidden />
          ) : item.kind === "reference" ? (
            <Puzzle aria-hidden />
          ) : (
            <FileText aria-hidden />
